var app=angular.module("kycSavingCurrentApp",[]);app.service("kycSavingCurrentService",["$http",function($http){var protocal=window.location.protocol;var host=window.location.host;var uRl=protocal+"//"+host+"/";this.save=function(data){var formData=new FormData;angular.forEach(data,function(value,key){if(value instanceof FileList){for(let i=0;i<value.length;i++){formData.append(key,value[i])}}else if(Array.isArray(value)){angular.forEach(value,function(file){formData.append(key+"[]",file)})}else{formData.append(key,value)}});return $http.post(uRl+"kyc-saving-current/save",formData,{transformRequest:angular.identity,headers:{"Content-Type":undefined}})};this.getAllKYCRecords=function(){var list=$http.get(uRl+"kyc-saving-current/getAllKycRecord");console.log(list);return list};this.getAllBranchListOfCOPs=function(userName){return $http.get(uRl+"kyc-saving-current/getAllBranchListOfCOPs/"+userName)};this.getAllBranchListOfBOM=function(userName){return $http.get(uRl+"kyc-saving-current/getAllBranchListOfBOM/"+userName)};this.getKycRecordById=function(id){return $http.get(uRl+"kyc-saving-current/get/"+id)};this.deleteKycRecord=function(id){return $http.delete(uRl+"kyc-saving-current/delete/"+id)};this.getAllKycRecordInJson=function(){return $http.get(uRl+"kyc-saving-current/getJsonFile")};this.getKycRecordsByAadharNo=function(adharNo){return $http.get(uRl+"kyc-saving-current/getAadhar/"+adharNo)};this.getRecordByCode=function(code){return $http.get(uRl+"kyc-saving-current/getRecordByCode/"+code)};this.updateKycRecord=function(data){var formData=new FormData;angular.forEach(data,function(value,key){if(value instanceof FileList){for(let i=0;i<value.length;i++){formData.append(key,value[i])}}else if(Array.isArray(value)){angular.forEach(value,function(file){formData.append(key+"[]",file)})}else{formData.append(key,value)}});return $http.put(uRl+"kyc-saving-current/update",formData,{transformRequest:angular.identity,headers:{"Content-Type":undefined}})};this.updateKycRecordCOPs=function(data){var formData=new FormData;angular.forEach(data,function(value,key){if(value instanceof FileList){for(let i=0;i<value.length;i++){formData.append(key,value[i])}}else if(Array.isArray(value)){angular.forEach(value,function(file){formData.append(key+"[]",file)})}else{formData.append(key,value)}});return $http.put(uRl+"kyc-saving-current/updateCOPs",formData,{transformRequest:angular.identity,headers:{"Content-Type":undefined}})}}]);